import React, { use } from "react";
import '../css/login.css';
import { Link, useNavigate } from "react-router-dom";

class Login extends React.Component {

    constructor(props){
        super(props);

        this.state = {
            phone: "",
            password: ""
        };
    }

    handleChange = (e) => {
        this.setState({
            [e.target.name]: e.target.value
        });
    }

    handleSubmit = (e) => {
        e.preventDefault();

        fetch("http://localhost:8000/api/login", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Accept": "application/json"
            },
            body: JSON.stringify({
                phone: this.state.phone,
                password: this.state.password
            })
        })
        .then(res => res.json())
        .then(json => {
            if (json.success) {
                localStorage.setItem("token", json.token);
 
                console.log("Login success");
                console.log(json);

                window.location.href = "/";
            } else {
                console.log("Login failed");
                console.log(json.message);

                alert(json.message);
            }
        })
        .catch(err => {
            console.log(err);
            alert("Something went wrong");
        });
    }


    render() {
        return (
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">
                    <div className="row align-items-center position-fixed top-50 start-50 translate-middle w-100">


                        <div className="col-xl-5 col-md-12">
                            <div className="d-flex justify-content-center align-items-center">
                                <div className="login-box-login shadow text-center item-back boder p-4 rounded-5">

                                    <h2 className="h2-login mb-4 text-color">Login</h2>

                                    <form onSubmit={this.handleSubmit}>

                                        <div className="form-floating mb-3">
                                            <input
                                                type="tel"
                                                className="form-control"
                                                name="phone"
                                                id="username"
                                                placeholder="Phone"
                                                value={this.state.phone}
                                                onChange={this.handleChange}
                                            />
                                            <label htmlFor="username">Phone</label>
                                        </div>

                                        <div className="form-floating mb-3 password-wrapper-login">
                                            <input
                                                type="password"
                                                className="form-control"
                                                name="password"
                                                id="password"
                                                placeholder="Password"
                                                minLength="8"
                                                value={this.state.password}
                                                onChange={this.handleChange}
                                            />
                                            <label htmlFor="password">Password</label>
                                        </div>

                                        <button type="submit" className="btn text-color boder w-100">
                                            <b>Login</b>
                                        </button>

                                    </form>

                                    <div className="mt-3">
                                        <p className="text-color">
                                            <b>Don't have an account?</b>
                                            <Link to="/register" className="btn text-color boder">
                                                Register
                                            </Link>
                                        </p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </main>
        );
    }
}

export default Login;
